fn solve(n: i8) -> Vec<char> {
    // We'll repeat the pattern "abba" to ensure that
    // for every i, s[i] != s[i+2], and we only use 'a' and 'b'.
    let n = n as usize;
    let pattern = ['a', 'b', 'b', 'a'];
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        result.push(pattern[i % 4]);
    }

    result
}

fn main() {
    // Examples
    println!("{:?}", solve(1)); // ["a"]
    println!("{:?}", solve(2)); // ["a", "b"]
    println!("{:?}", solve(3)); // ["a", "b", "b"]
    println!("{:?}", solve(4)); // ["a", "b", "b", "a"]
    println!("{:?}", solve(7)); // ["a", "b", "b", "a", "a", "b", "b"]
}